private val workoutLookup=workoutRows.mapValues {(_,row)->workoutKeys.zip(row.split('|')).toMap()}
fun workoutTranslation(text:String,language:String)=workoutLookup[language]?.get(text)
fun workoutText(key:String,language:String,vararg values:Any):String {
    var text=workoutTranslation(key,language) ?: workoutTranslation(key,"en") ?: key
    values.forEachIndexed {index,value->text=text.replace("{$index}",value.toString())}
    return text
}
